import os,json,subprocess
from pathlib import Path
root=Path("/srv/projects/lowcost-europa")
names=("lowcost-europa-backup","lowcost-europa-offsite-backup","lowcost-europa-offsite-backup-health")
oldprefix="/usr/local/sbin/lowcost-europa-"
out={"project":"lowcost-europa","status":"BLOCKED","changed":False}
old_paths=[Path("/usr/local/sbin")/n for n in names]
new_paths=[root/"bin"/n for n in names]
def states():
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=5).stdout.strip() for n in ("ssh","nginx","lowcost-europa","fadego-staging","pink-iptv-backend","pm2-root")}
removed=[]
try:
 if not root.is_dir() or root.is_symlink():raise RuntimeError("invalid_project_root")
 for old,new in zip(old_paths,new_paths):
  if not old.is_symlink() or old.resolve(strict=True)!=new or not new.is_file() or new.is_symlink():raise RuntimeError("alias_target_changed")
  if subprocess.run(["/bin/sh","-n",str(new)],capture_output=True,timeout=7).returncode!=0:raise RuntimeError("canonical_script_syntax_failed")
 for unit in ("lowcost-europa-backup.service","lowcost-europa-offsite-backup.service","lowcost-europa-offsite-backup-health.service"):
  p=Path("/etc/systemd/system")/unit
  if not p.is_file() or p.is_symlink() or oldprefix.encode() in p.read_bytes():raise RuntimeError("unit_still_references_alias")
  if subprocess.run(["systemd-analyze","verify",str(p)],capture_output=True,timeout=10).returncode!=0:raise RuntimeError("canonical_unit_invalid")
 found=[]
 locations=("/etc/systemd/system","/etc/cron.d","/etc/cron.daily","/etc/cron.weekly","/etc/cron.monthly","/usr/local/bin","/usr/local/sbin")
 for base in locations:
  p=Path(base)
  if not p.is_dir():continue
  for item in p.iterdir():
   try:
    if item.is_symlink() or not item.is_file() or item.stat().st_size>100000:continue
    content=item.read_bytes()
    if any(str(old).encode() in content for old in old_paths):found.append(str(item))
   except OSError:pass
 if found:raise RuntimeError("scheduled_consumer_references_legacy_script")
 for p in Path("/proc").iterdir():
  if not p.name.isdecimal() or int(p.name) in (os.getpid(),os.getppid()):continue
  try:
   comm=(p/"comm").read_text().strip()
   if comm not in ("sh","bash","dash","cron","crond"):continue
   cmd=(p/"cmdline").read_bytes()
   if any(str(old).encode() in cmd for old in old_paths):raise RuntimeError("legacy_script_currently_running")
  except OSError:pass
 baseline=states()
 for old in old_paths:
  old.unlink();removed.append(old)
 if any(old.exists() or old.is_symlink() for old in old_paths) or states()!=baseline:raise RuntimeError("post_cleanup_regression")
 out.update(status="ALIASES_REMOVED_VERIFIED",changed=True,symlinks_removed=[str(x) for x in old_paths],canonical_scripts=[str(x) for x in new_paths],services_unchanged=True,scheduled_refs_found=0)
except Exception as e:
 out["reason"]=str(e)[:150]
 if removed:
  restored=[]
  for old,new in zip(old_paths,new_paths):
   if old in removed:
    try:
     if not old.exists() and not old.is_symlink():os.symlink(str(new),old);restored.append(str(old))
    except Exception:pass
  out["rollback"]="RESTORED" if len(restored)==len(removed) else "INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="ALIASES_REMOVED_VERIFIED":raise SystemExit(3)
